  var TYPE_INDEX = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
  var TURRET = {
    bolt:   { cost: 50,  damage: 26,  period: 8,  range: 300, splash: 0,  slow: 0,  pierce: false, ground: true,  air: true  },
    cannon: { cost: 90,  damage: 60,  period: 24, range: 260, splash: 90, slow: 0,  pierce: false, ground: true,  air: false },
    frost:  { cost: 70,  damage: 10,  period: 12, range: 240, splash: 0,  slow: 30, pierce: false, ground: true,  air: true  },
    lance:  { cost: 120, damage: 180, period: 36, range: 360, splash: 0,  slow: 0,  pierce: true,  ground: true,  air: false },
    flak:   { cost: 80,  damage: 40,  period: 10, range: 320, splash: 70, slow: 0,  pierce: false, ground: false, air: true  }
  };
  var ENEMY = {
    grunt:     { hp: 60,  speed: 10, bounty: 4, leak: 1, air: false, baseArmor: 0 },
    runner:    { hp: 40,  speed: 20, bounty: 4, leak: 1, air: false, baseArmor: 0 },
    wisp:      { hp: 50,  speed: 12, bounty: 6, leak: 2, air: true,  baseArmor: 0 },
    brute:     { hp: 150, speed: 6,  bounty: 9, leak: 3, air: false, baseArmor: -1 },
    splitter:  { hp: 90,  speed: 8,  bounty: 6, leak: 2, air: false, baseArmor: 0 },
    mender:    { hp: 70,  speed: 8,  bounty: 7, leak: 2, air: false, baseArmor: 0 },
    splitling: { hp: 22,  speed: 12, bounty: 1, leak: 1, air: false, baseArmor: 0 }
  };
  var GROUND_PTS = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
  var AIR_PTS = [[0, 6], [21, 6], [21, 11], [23, 11]];
  var GROUND_LEN = 4600;
  var AIR_LEN = 2600;
  var SLOT_TILES = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];

  function mulberry32(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return (t ^ (t >>> 14)) >>> 0;
    };
  }

  function fnv1a(str) {
    var h = 0x811c9dc5;
    for (var i = 0; i < str.length; i++) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 0x01000193);
    }
    return (h >>> 0).toString(16).padStart(8, "0");
  }

  function pointAlong(air, progress) {
    var pts = air ? AIR_PTS : GROUND_PTS;
    var d = progress;
    for (var i = 0; i < pts.length - 1; i++) {
      var x0 = pts[i][0] * 100, y0 = pts[i][1] * 100;
      var x1 = pts[i + 1][0] * 100, y1 = pts[i + 1][1] * 100;
      var dx = x1 - x0, dy = y1 - y0;
      var seg = Math.abs(dx) + Math.abs(dy);
      if (d <= seg || i === pts.length - 2) {
        var t = seg > 0 ? d / seg : 0;
        if (t < 0) t = 0;
        if (t > 1) t = 1;
        return [x0 + dx * t, y0 + dy * t];
      }
      d -= seg;
    }
    return [2300, 1100];
  }

  function enemyView(e) {
    return {
      id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp,
      x: e.x, y: e.y, air: e.air ? 1 : 0, armor: e.armor,
      speed: e.speed, slowed: e.slow, remaining: e.remaining
    };
  }

  function turretView(t) {
    return { slot: t.slot, type: t.type, tier: t.tier, x: t.x, y: t.y, range: t.range };
  }

  function makeTurret(slot, type, tier) {
    var spec = TURRET[type];
    var dmg = spec.damage;
    if (tier >= 2) dmg = Math.floor(dmg * 16 / 10);
    if (tier >= 3) dmg = Math.floor(dmg * 16 / 10);
