    function scaleHp(w) {
      if (w > mScale.length - 1) {
        for (var k = mScale.length; k <= w; k++) mScale[k] = Math.floor(mScale[k - 1] * 108 / 100);
      }
      return mScale[w];
    }

    function genComposition(w) {
      if (comps[w]) return comps[w].slice();
      var avail = [
        ["grunt", 10, 1], ["runner", 4, 2], ["wisp", 3, 3],
        ["brute", 3, 4], ["splitter", 2, 6], ["mender", 1, 8]
      ].filter(function (a) { return a[2] <= w; });
      var sum = avail.reduce(function (s, a) { return s + a[1]; }, 0);
      var count = 4 + Math.floor(3 * w / 5);
      var list = [];
      for (var i = 0; i < count; i++) {
        var r = rng() % sum;
        for (var j = 0; j < avail.length; j++) {
          if (r < avail[j][1]) { list.push(avail[j][0]); break; }
          r -= avail[j][1];
        }
      }
      comps[w] = list;
      return list.slice();
    }

    function armorOf(type, wave) {
      if (type === "grunt") return Math.floor(wave / 4);
      if (type === "brute") return 6 + wave;
      if (type === "splitling") return 0;
      return 0;
    }

    function spawnEnemy(type, wave, progress) {
      var spec = ENEMY[type];
