function createStrategy() {
  var ORDER = [
    [1, "bolt"], [3, "cannon"], [6, "cannon"], [8, "flak"],
    [11, "lance"], [10, "flak"], [13, "cannon"], [5, "cannon"],
    [12, "flak"], [14, "lance"], [4, "cannon"], [2, "frost"],
    [9, "lance"], [0, "bolt"], [7, "lance"], [15, "frost"]
  ];
  var BASE = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DPS = { bolt: 3.25, cannon: 2.5, frost: 0.833, lance: 5, flak: 4 };
  function closer(a, b) {
    if (a.remaining !== b.remaining) return a.remaining < b.remaining;
    return a.id < b.id;
  }
  return {
    plan: function (s) {
      var acts = [];
      var gold = s.gold;
      var i, sl;
      for (i = 0; i < ORDER.length && acts.length < 32; i++) {
        var slot = ORDER[i][0], type = ORDER[i][1];
        sl = s.slots[slot];
        if (sl.turret) continue;
        if (gold >= BASE[type]) {
          acts.push({ op: "build", slot: slot, type: type });
          gold -= BASE[type];
        }
      }
      // Once the board is reasonably full, spend the rest on upgrades.
      var upOrder = [11, 8, 10, 12, 5, 6, 3, 13, 14, 1, 4, 9, 7, 2, 0, 15];
      for (var pass = 0; pass < 2 && acts.length < 32; pass++) {
        for (i = 0; i < upOrder.length && acts.length < 32; i++) {
          slot = upOrder[i];
          sl = s.slots[slot];
          if (!sl.turret) continue;
          var tier = sl.turret.tier;
          if (pass === 0 && tier !== 1) continue;
          if (pass === 1 && tier !== 2) continue;
          var t = sl.turret.type;
          var cost = pass === 0 ? BASE[t] : BASE[t] * 2;
          if (gold >= cost) {
            acts.push({ op: "upgrade", slot: slot });
            gold -= cost;
          }
        }
      }
      return acts;
    },
    target: function (t, cands) {
      if (!cands.length) return 0;
      if (t.type === "cannon" || t.type === "flak") {
        var splash = t.type === "cannon" ? 90 : 70;
        var best = cands[0], bestScore = -1;
        for (var i = 0; i < cands.length; i++) {
          var c = cands[i], score = 0;
          for (var j = 0; j < cands.length; j++) {
            var dx = cands[j].x - c.x, dy = cands[j].y - c.y;
            if (dx * dx + dy * dy <= splash * splash) score += 10 + cands[j].hp / 100;
          }
          if (score > bestScore || (score === bestScore && closer(c, best))) {
            best = c; bestScore = score;
          }
        }
        return best.id;
      }
      if (t.type === "lance") {
        var target = cands[0];
        for (var k = 1; k < cands.length; k++) {
          var cc = cands[k];
          if (cc.armor > 0) {
            if (target.armor === 0 || cc.hp > target.hp || (cc.hp === target.hp && closer(cc, target))) target = cc;
          } else if (target.armor === 0 && closer(cc, target)) target = cc;
        }
        return target.id;
      }
      if (t.type === "frost") {
        for (var f = 0; f < cands.length; f++) if (!cands[f].slowed) return cands[f].id;
      }
      var b = cands[0];
      for (var q = 1; q < cands.length; q++) if (closer(cands[q], b)) b = cands[q];
      return b.id;
    }
  };
}

