(function () {
  "use strict";

  var DURATION = 100;
  var TICK_RATE = 20;
  var TAU = Math.PI * 2;

  function mulberry32(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return (t ^ (t >>> 14)) >>> 0;
    };
  }
  var visualRand = mulberry32(42);
  function vr() { return visualRand() / 4294967296; }
  function vrRange(a, b) { return a + (b - a) * vr(); }

  function makeCanvas(w, h) {
    var c = document.createElement("canvas");
    c.width = w;
    c.height = h;
    return c;
  }

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function lerp(a, b, t) { return a + (b - a) * t; }

