// ---------------------------------------------------------------- audio
var AudioSys = (function () {
  var AC = window.AudioContext || window.webkitAudioContext;
  var ctx = null, master = null, comp = null, noiseBuffer = null, wind = null, windGain = null;
  var active = false;
  var voices = [];
  var shotTimes = [], killTimes = [];
  var fallPlayed = false;
  var arng = mulberry32(4242);
  function ar() { return arng() / 4294967296; }
  try {
    if (AC) {
      ctx = new AC();
      master = ctx.createGain();
      master.gain.value = 0;
      comp = ctx.createDynamicsCompressor();
      comp.threshold.value = -18;
      comp.knee.value = 16;
      comp.ratio.value = 4;
      comp.attack.value = 0.003;
      comp.release.value = 0.25;
      master.connect(comp);
      comp.connect(ctx.destination);
      var len = Math.floor(ctx.sampleRate * 1.2);
      noiseBuffer = ctx.createBuffer(1, len, ctx.sampleRate);
      var data = noiseBuffer.getChannelData(0);
      for (var i = 0; i < len; i++) data[i] = ar() * 2 - 1;
      if (ctx.state === "suspended") ctx.resume().catch(function () {});
    }
  } catch (e) { ctx = null; }
  function resume() {
    if (ctx && ctx.state === "suspended") ctx.resume().catch(function () {});
  }
  window.addEventListener("pointerdown", resume, { passive: true });
  window.addEventListener("keydown", resume);
  function now() { return ctx ? ctx.currentTime : 0; }
  function panNode(x) {
    if (!ctx.createStereoPanner) return null;
    var p = ctx.createStereoPanner();
    p.pan.value = clamp((x / 24) * 2 - 1, -1, 1);
    return p;
  }
  function route(node, x) {
    var p = panNode(x);
    if (p) { node.connect(p); p.connect(master); } else node.connect(master);
  }
  function track(source) {
    voices.push(source);
    source.onended = function () {
      var ix = voices.indexOf(source);
      if (ix >= 0) voices.splice(ix, 1);
    };
  }
  function stopVoices() {
    var t = now();
    for (var i = voices.length - 1; i >= 0; i--) {
      try { voices[i].stop(t); } catch (e) {}
    }
    voices.length = 0;
  }
  function setActive(v, simTime) {
    active = !!v;
    if (!ctx) return;
    var t = now();
    master.gain.cancelScheduledValues(t);
    master.gain.setTargetAtTime(active ? 0.33 : 0, t, 0.008);
    if (!active) {
      stopVoices();
    } else if (windGain) {
      windGain.gain.setTargetAtTime((fallTick >= 0 && simTime >= fallTime) ? 0.04 : 0.0001, t, 0.08);
    }
    if (active && fallTick >= 0 && simTime >= fallTime) startWind();
  }
  function tone(freq, dur, type, vol, x, slide) {
    if (!active || !ctx) return;
    var t = now();
    var o = ctx.createOscillator();
    var g = ctx.createGain();
    o.type = type || "sine";
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g);
    route(g, x);
    o.start(t);
    o.stop(t + dur + 0.02);
    track(o);
  }
  function noise(dur, freq, q, vol, x, type) {
    if (!active || !ctx || !noiseBuffer) return;
    var t = now();
